/// <summary>
/// CoC on the run method to inject custom logic before the standard posting process executes.
/// </summary>
public void run()
{
    // Get the parameter tables that hold information about the current posting job.
    PurchParmTable  purchParmTable;
    PurchParmUpdate purchParmUpdate = this.purchParmUpdate();

    select purchParmTable
        where purchParmTable.ParmId == purchParmUpdate.ParmId;

    // This logic should only run when posting from a purchase order.
    if (purchParmTable)
    {
        Set             salesIdSet = new Set(Types::String);
        PurchParmLine   purchParmLine;
        PurchLine       purchLine;
        SalesId         salesId;
        PackingSlipId   packingSlipId;

        // Iterate through all the lines that are marked for posting in this transaction.
        // The purchParmLine table contains a record for each line being processed.
        while select purchParmLine
            where purchParmLine.ParmId      == purchParmTable.ParmId
               && purchParmLine.TableRefId  == purchParmTable.TableRefId
               && purchParmLine.OrigPurchId == purchParmTable.PurchId
        {
            // Find the original PurchLine record from the RecId stored in the parameter line.
            purchLine = PurchLine::findRecId(purchParmLine.PurchLineRecId, false);

            // If the line exists and has a value in the custom sales order reference field, add it to our set.
            // A set automatically handles uniqueness, so it's perfect for finding all unique sales order IDs.
            if (purchLine && purchLine.METReplenishmentSOReference)
            {
                salesIdSet.add(purchLine.METReplenishmentSOReference);
            }
        }

        // --- Validation Step ---
        // If the set contains more than one unique Sales Order ID, it means the user is trying to
        // post lines linked to different sales orders. We stop the process here.
        if (salesIdSet.elements() > 1)
        {
            throw error("Lines for multiple sales orders cannot be posted in the same product receipt. Please select lines that reference the same sales order.");
        }

        // --- Main Logic Step ---
        // If the set contains exactly one Sales Order ID, we proceed.
        if (salesIdSet.elements() == 1)
        {
            // Get the single SalesId from the set.
            SetEnumerator   se = salesIdSet.getEnumerator();
            se.moveNext();
            salesId = se.current();

            // Find the corresponding packing slip journal for the sales order.
            // We order by CreatedDateTime descending to get the latest one, but this can be adjusted.
            CustPackingSlipJour custPackingSlipJour;

            select firstonly PackingSlipId from custPackingSlipJour
                order by CreatedDateTime desc
                where custPackingSlipJour.SalesId == salesId;

            if (custPackingSlipJour)
            {
                packingSlipId = custPackingSlipJour.PackingSlipId;

                // Before assigning the ID, check if a product receipt with this ID already exists to prevent duplicates.
                if (VendPackingSlipJour::exist(packingSlipId))
                {
                    throw error(strFmt("A product receipt with ID '%1' already exists. The process cannot continue.", packingSlipId));
                }

                // Set the found packing slip ID as the new product receipt ID for this posting.
                // The standard posting logic will now use this ID instead of generating a new one from a number sequence.
                purchParmTable.ParmId = packingSlipId;
                purchParmTable.Num    = packingSlipId; // The Num field is often used for the visible voucher number.

                this.parmId(packingSlipId);
            }
            else
            {
                // If no packing slip is found for the sales order, stop the process.
                throw error(strFmt("The referenced sales order %1 has not been packing slip posted. Please post the sales order packing slip first.", salesId));
            }
        }
    }

    // Call next 'run()' to continue with the standard D365 posting process.
    // Our modifications to the purchParmTable will be used by this standard process.
    next run();
}
